auto func (auto value){ 
    return std::make_tuple(
        std::is_integral_v<decltype(value)>,
        std::count_if(std::begin(value), std::end(value), ::isdigit),
        std::any_of(std::begin(value), std::end(value), ::isalpha)
    );
}

auto func (auto value){  
    int count = 0;  
    for (char c : to_string(value)) {  
        if (isdigit(c)) {  
            count++;  
        }  
    }  
    return count;  
}

auto func (auto value){ 
    int count = 0;
    for(auto& c : to_string(value)){
        if(isdigit(c)) count++;
    }
    return count;
}

auto func (auto value){ 
    int count = 0;
    for (char c : value) {
        if (isdigit(c)) {
            ++count;
        }
    }
    return count;
}
